for (const lang of ['ru','ko']) Object.assign(copy[lang], window.ACE_CONTENT?.[lang] || {});
const config = window.ACE_CONFIG || {};
let language = 'ru';
try { if (localStorage.getItem('ace-language') === 'ko') language = 'ko'; } catch {}
const safeURL = value => { try { const u=new URL(value); return u.protocol === 'https:' ? u.href : ''; } catch { return ''; } };
const localized = value => typeof value === 'string' ? value : value?.[language] || value?.ru || '';
const menu = document.querySelector('.menu-toggle');
const mobileNav = document.querySelector('#mobile-nav');
function setMenu(open) { mobileNav.hidden=!open;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',language==='ko'?(open?'메뉴 닫기':'메뉴 열기'):(open?'Закрыть меню':'Открыть меню')); }
function render() {
  document.documentElement.lang=language;
  document.title=language==='ko'?'Ace Place — 안산의 파티 공간':'Ace Place — пространство для твоей вечеринки в Ансане';
  document.querySelectorAll('[data-i18n]').forEach(el=>{const value=copy[language][el.dataset.i18n];if(value)el.innerHTML=value;});
  document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',copy[language][el.dataset.i18nAria]));
  document.querySelectorAll('[data-money]').forEach(el=>{const amount=config.pricing?.[el.dataset.money];el.textContent=Number.isFinite(amount)?new Intl.NumberFormat(language==='ko'?'ko-KR':'ru-RU').format(amount)+(language==='ko'?'원':' ₩'):copy[language].priceFallback;});
  document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===language)));
  document.querySelectorAll('[data-address]').forEach(el=>el.textContent=localized(config.address));
  document.querySelectorAll('[data-config]').forEach(el=>el.textContent=localized(config[el.dataset.config])||copy[language][el.dataset.fallback]);
  const map='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(config.mapQuery||'경기 안산시 단원구 중앙대로 829');
  document.querySelectorAll('[data-map]').forEach(el=>el.href=map);
  const frame=document.querySelector('.map iframe');
  frame.src='https://maps.google.com/maps?q='+encodeURIComponent(config.mapQuery||'경기 안산시 단원구 중앙대로 829')+'&t=&z=16&ie=UTF8&iwloc=&output=embed&hl='+language;
  frame.title=language==='ko'?'Ace Place 위치 지도':'Ace Place — карта расположения';
  document.querySelectorAll('[data-booking]').forEach(el=>{el.href=safeURL(config.bookingUrl)||'#contacts';if(safeURL(config.bookingUrl)){el.target='_blank';el.rel='noopener';el.setAttribute('aria-label',copy[language].telegramBooking);}});
  const links=document.querySelector('#contact-links');links.replaceChildren();
  function addLink(label,href){const a=document.createElement('a');a.textContent=label+' ↗';a.href=href;if(href.startsWith('https:')){a.target='_blank';a.rel='noopener';}links.append(a);}
  if(config.phone && /^\+?[\d\s()−-]{5,25}$/.test(config.phone))addLink(config.phone,'#contacts');
  if(config.email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.email))addLink(config.email,'mailto:'+config.email);
  for(const [key,label] of [['telegram','Telegram'],['instagram','Instagram'],['bookingUrl',copy[language].telegramBooking]]){const url=safeURL(config[key]);if(url)addLink(label,url);}
  document.querySelector('.contact-empty').hidden=links.children.length>0;
  document.querySelector('.close-lightbox').setAttribute('aria-label',language==='ko'?'사진 닫기':'Закрыть фото');
  document.querySelectorAll('[data-alt]').forEach(im=>im.alt=copy[language][im.dataset.alt]);
  document.querySelectorAll('nav').forEach(n=>n.setAttribute('aria-label',language==='ko'?'메인 메뉴':'Навигация'));
  setMenu(false);
}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{language=b.dataset.lang;try{localStorage.setItem('ace-language',language);}catch{}render();}));
menu.addEventListener('click',()=>setMenu(mobileNav.hidden));
mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false);});
const lightbox=document.querySelector('#lightbox');
const photoButtons=[...document.querySelectorAll('[data-photo]')];
let photoIndex=0;
function showPhoto(index){photoIndex=(index+photoButtons.length)%photoButtons.length;const b=photoButtons[photoIndex];const im=lightbox.querySelector('img');im.src=b.dataset.photo;im.alt=b.querySelector('img').alt;document.querySelector('.lightbox-counter').textContent=(photoIndex+1)+' / '+photoButtons.length;}
photoButtons.forEach((b,i)=>b.addEventListener('click',()=>{showPhoto(i);lightbox.showModal();}));
document.querySelector('.lightbox-prev').addEventListener('click',()=>showPhoto(photoIndex-1));
document.querySelector('.lightbox-next').addEventListener('click',()=>showPhoto(photoIndex+1));
lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(photoIndex-1);}if(e.key==='ArrowRight'){e.preventDefault();showPhoto(photoIndex+1);}});
document.querySelector('.close-lightbox').addEventListener('click',()=>lightbox.close());
lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close();});
if('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(s=>{s.classList.add('js-reveal');observer.observe(s);});}
render();
